ALTER TABLE sales.orders CLUSTER BY (TO_DATE(order_ts), region);

-- depth and overlap statistics for the key
SELECT SYSTEM$CLUSTERING_INFORMATION('sales.orders');

SELECT * FROM sales.orders AT (OFFSET => -60*30);           -- 30 minutes ago
SELECT * FROM sales.orders BEFORE (STATEMENT => '01b2c3d4-...');
UNDROP TABLE sales.orders;

CREATE DATABASE analytics_dev CLONE analytics;              -- zero-copy
CREATE TABLE sales.orders_backup CLONE sales.orders
  AT (TIMESTAMP => '2026-11-16 08:00:00'::TIMESTAMP_LTZ);
